def parse_z3_formula(formula_str: str, var_type: str = "auto") -> z3.ExprRef | None:
    """Safely parse a string into a z3 expression.

    Supports:
      - Arithmetic: +, -, *, /, **, ==, !=, <, >, <=, >= (Real variables)
      - Boolean: Implies, And, Or, Not, == True/False (Bool variables)
      - Functions: sum, max, min, abs (z3-compatible wrappers)
      - Chained comparisons: 0 <= x <= 9 → And(0 <= x, x <= 9)
      - Python logic: x > 0 and y > 0 → And(x > 0, y > 0)
      - Modular arithmetic: N % 7 == 0 (auto-detects Int context)
    Auto-declares unknown variables as z3.Real, z3.Int, or z3.Bool based on context.
    Returns None on parse failure or non-boolean result.
    """
    if not formula_str or not formula_str.strip():
        return None

    formula_str = _preprocess_formula(formula_str)

    # Detect boolean mode BEFORE AST rewrite (rewrite adds And/Or/Not which
    # would falsely trigger boolean detection for arithmetic formulas)
    pre_rewrite_bool = (var_type == "bool") or (
        var_type == "auto" and _is_boolean_formula(formula_str)
    )

    # AST rewrite: chained comparisons, python and/or/not, tuple constraints
    formula_str = _ast_rewrite(formula_str)

    # Detect integer context
    use_int = _needs_int_vars(formula_str)

    # In integer context, replace // with / (Z3 Int / is integer division)
    if use_int:
        formula_str = formula_str.replace('//', '/')

    # Try with detected variable type
    result = _try_eval(formula_str, var_type, use_int, is_bool=pre_rewrite_bool)
    if result is not None:
