    # Fallback: if Real failed, try Int (handles modulo/floor-div edge cases)
    if not use_int:
        result = _try_eval(formula_str, var_type, use_int=True, is_bool=pre_rewrite_bool)
        if result is not None:
            return result

    logger.debug("Failed to parse z3 formula: %s", formula_str)
    return None


def check_equivalence(f1: z3.ExprRef, f2: z3.ExprRef, timeout_ms: int = 1000) -> bool:
    """Check if two z3 formulas are logically equivalent (f1 ⟺ f2)."""
    if not z3.is_bool(f1) or not z3.is_bool(f2):
        return False
    s = z3.Solver()
    s.set("timeout", timeout_ms)
    s.add(z3.Not(f1 == f2))
    result = s.check()
    return result == z3.unsat


